@@ -7438,1 +7438,1 @@
-  // Scalar Keccak-f[1600], keeping the 25 state lanes in GPRs across rounds.
+  // Scalar Keccak-f[1600]. Spill two lanes when preserving frame pointers.
@@ -7448,0 +7448,1 @@
+  static const int SHA3_GPR_FRAME_FP = 176;
@@ -7460,0 +7461,2 @@
+  static const int SHA3_LANE24_SPILL = 160;
+  static const int SHA3_LANE23_SPILL = 168;
@@ -7463,0 +7466,1 @@
+    const bool can_use_fp = !PreserveFramePointer;
@@ -7467,1 +7471,3 @@
-    Register lane20 = x29, lane21 = x30, lane22 = x31, lane23 = ra,  lane24 = fp;
+    Register lane20 = x29, lane21 = x30, lane22 = x31;
+    Register lane23 = can_use_fp ? ra : noreg;
+    Register lane24 = can_use_fp ? fp : noreg;
@@ -7492,1 +7498,1 @@
-    for (int i = 0; i < 24; i++) {
+    for (int i = 0; i < (r.can_use_fp ? 24 : 22); i++) {
@@ -7495,0 +7501,10 @@
+    if (!r.can_use_fp) {
+      // Preserve base through lane18's load, and x10 while it still holds buf.
+      assert(base == r.lane18 || base == r.tmp0, "unexpected state base");
+      Register tmp = base == r.tmp0 ? r.tmp1 : r.tmp0;
+      assert_different_registers(base, tmp);
+      __ ld(tmp, Address(base, 23 * 8));
+      __ sd(tmp, Address(sp, SHA3_LANE23_SPILL));
+      __ ld(tmp, Address(base, 24 * 8));
+      __ sd(tmp, Address(sp, SHA3_LANE24_SPILL));
+    }
@@ -7506,1 +7522,1 @@
-    for (int i = 0; i < 24; i++) {
+    for (int i = 0; i < (r.can_use_fp ? 24 : 22); i++) {
@@ -7510,0 +7526,7 @@
+    if (!r.can_use_fp) {
+      // Keep tmp1 intact: it holds the multi-block return offset.
+      __ ld(r.lane0, Address(sp, SHA3_LANE23_SPILL));
+      __ sd(r.lane0, Address(base, 23 * 8));
+      __ ld(r.lane0, Address(sp, SHA3_LANE24_SPILL));
+      __ sd(r.lane0, Address(base, 24 * 8));
+    }
@@ -7535,2 +7558,4 @@
-    // Restore fp to the value expected by leave().
-    __ addi(fp, sp, SHA3_GPR_FRAME + 16);
+    if (!PreserveFramePointer) {
+      // Restore fp to the value expected by leave().
+      __ addi(fp, sp, SHA3_GPR_FRAME + 16);
+    }
@@ -7571,1 +7596,6 @@
-    __ xorr(tmp0, tmp0, lane24);  // c4
+    if (r.can_use_fp) {
+      __ xorr(tmp0, tmp0, lane24);  // c4
+    } else {
+      __ ld(tmp1, Address(sp, SHA3_LANE24_SPILL));
+      __ xorr(tmp0, tmp0, tmp1);
+    }
@@ -7615,1 +7645,6 @@
-      __ xorr(tmp0, tmp0, lane23);  // c3
+      if (r.can_use_fp) {
+        __ xorr(tmp0, tmp0, lane23);  // c3
+      } else {
+        __ ld(tmp1, Address(sp, SHA3_LANE23_SPILL));
+        __ xorr(tmp0, tmp0, tmp1);
+      }
@@ -7621,1 +7656,7 @@
-      __ xorr(lane23, lane23, tmp3);
+      if (r.can_use_fp) {
+        __ xorr(lane23, lane23, tmp3);
+      } else {
+        // tmp1 still holds lane23 from the c3 calculation.
+        __ xorr(tmp1, tmp1, tmp3);
+        __ sd(tmp1, Address(sp, SHA3_LANE23_SPILL));
+      }
@@ -7642,1 +7683,7 @@
-      __ xorr(lane24, lane24, tmp0);
+      if (r.can_use_fp) {
+        __ xorr(lane24, lane24, tmp0);
+      } else {
+        __ ld(tmp1, Address(sp, SHA3_LANE24_SPILL));
+        __ xorr(tmp1, tmp1, tmp0);
+        __ sd(tmp1, Address(sp, SHA3_LANE24_SPILL));
+      }
@@ -7668,2 +7715,9 @@
-    __ rori(lane19, lane23,  8);
-    __ rori(lane23, lane15, 23);
+    if (r.can_use_fp) {
+      __ rori(lane19, lane23,  8);
+      __ rori(lane23, lane15, 23);
+    } else {
+      __ ld(tmp1, Address(sp, SHA3_LANE23_SPILL));
+      __ rori(lane19, tmp1, 8);
+      __ rori(tmp1, lane15, 23);
+      __ sd(tmp1, Address(sp, SHA3_LANE23_SPILL));
+    }
@@ -7671,2 +7725,9 @@
-    __ rori(lane4,  lane24, 50);
-    __ rori(lane24, lane21, 62);
+    if (r.can_use_fp) {
+      __ rori(lane4,  lane24, 50);
+      __ rori(lane24, lane21, 62);
+    } else {
+      __ ld(tmp1, Address(sp, SHA3_LANE24_SPILL));
+      __ rori(lane4, tmp1, 50);
+      __ rori(tmp1, lane21, 62);
+      __ sd(tmp1, Address(sp, SHA3_LANE24_SPILL));
+    }
@@ -7688,1 +7749,14 @@
-    bcax5_gpr(lane20, lane21, lane22, lane23, lane24, tmp0, tmp1);
+    if (r.can_use_fp) {
+      bcax5_gpr(lane20, lane21, lane22, lane23, lane24, tmp0, tmp1);
+    } else {
+      // Reuse Theta's slots to borrow the completed row-zero lanes until Iota.
+      __ sd(lane0, Address(sp, SHA3_LANE4_SPILL));
+      __ sd(lane1, Address(sp, SHA3_LANE9_SPILL));
+      __ ld(lane0, Address(sp, SHA3_LANE24_SPILL));
+      __ ld(lane1, Address(sp, SHA3_LANE23_SPILL));
+      bcax5_gpr(lane20, lane21, lane22, lane1, lane0, tmp0, tmp1);
+      __ sd(lane0, Address(sp, SHA3_LANE24_SPILL));
+      __ sd(lane1, Address(sp, SHA3_LANE23_SPILL));
+      __ ld(lane0, Address(sp, SHA3_LANE4_SPILL));
+      __ ld(lane1, Address(sp, SHA3_LANE9_SPILL));
+    }
@@ -7732,1 +7806,1 @@
-    __ subi(sp, sp, SHA3_GPR_FRAME);
+    __ subi(sp, sp, r.can_use_fp ? SHA3_GPR_FRAME : SHA3_GPR_FRAME_FP);
@@ -7848,1 +7922,1 @@
-    __ subi(sp, sp, SHA3_GPR_FRAME);
+    __ subi(sp, sp, r.can_use_fp ? SHA3_GPR_FRAME : SHA3_GPR_FRAME_FP);

@@ -434,1 +434,1 @@
-  if (UseSHA && UseZbb && !PreserveFramePointer) {
+  if (UseSHA && UseZbb) {
@@ -439,5 +439,1 @@
-    if (PreserveFramePointer) {
-      warning("SHA3 intrinsics are not available with PreserveFramePointer enabled.");
-    } else {
-      warning("Intrinsics for SHA3-224, SHA3-256, SHA3-384 and SHA3-512 crypto hash functions not available on this CPU.");
-    }
+    warning("Intrinsics for SHA3-224, SHA3-256, SHA3-384 and SHA3-512 crypto hash functions not available on this CPU.");
